ALTER TABLE public.app_roles ADD COLUMN IF NOT EXISTS catalog_state text NOT NULL DEFAULT 'custom', ADD COLUMN IF NOT EXISTS catalog_group text, ADD COLUMN IF NOT EXISTS catalog_pending text[] NOT NULL DEFAULT '{}';
CREATE TABLE private.standard_role_catalog_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), before_data jsonb NOT NULL, after_data jsonb, mapping jsonb NOT NULL);
REVOKE ALL ON private.standard_role_catalog_runs FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.standard_role_catalog_setup() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE snapshot_ uuid; spec_ jsonb; role_ record; source_ record; changes_ jsonb:='[]'; preview_ jsonb; title_ text; mapping_ jsonb := '[{"id":"role-standard-mkt-director","name":"Giám đốc Marketing","group":"Marketing","source":"role-leader-marketing","title":"b5e00000-0000-4000-8000-000000000120"},{"id":"role-standard-mkt-head","name":"Trưởng phòng Marketing","group":"Marketing","source":"role-leader-marketing","title":"b5e00000-0000-4000-8000-000000000101"},{"id":"role-standard-mkt-team","name":"Trưởng nhóm Marketing","group":"Marketing","source":"role-leader-marketing"},{"id":"role-standard-design-head","name":"Trưởng phòng Thiết kế","group":"Thiết kế","source":"role-designer","title":"b5e00000-0000-4000-8000-000000000103"},{"id":"role-standard-design-team","name":"Trưởng nhóm Thiết kế","group":"Thiết kế","source":"role-designer"},{"id":"role-standard-design-staff","name":"Nhân viên Thiết kế","group":"Thiết kế","source":"role-designer","title":"b5e00000-0000-4000-8000-000000000104"},{"id":"role-standard-account-chief","name":"Kế toán trưởng","group":"Vận hành","source":"role-0k2hmw8r","title":"b5e00000-0000-4000-8000-000000000107"},{"id":"role-standard-account-stock","name":"Kế toán kho","group":"Vận hành","source":"role-0k2hmw8r","title":"b5e00000-0000-4000-8000-000000000108"},{"id":"role-standard-proc-head","name":"Trưởng phòng Mua hàng & Giao vận","group":"Vận hành","source":"role-xim870m3","title":"b5e00000-0000-4000-8000-000000000109"},{"id":"role-standard-buyer","name":"Thu mua","group":"Vận hành","source":"role-xim870m3","title":"b5e00000-0000-4000-8000-000000000110"}]';
BEGIN
 IF auth.uid() IS NULL OR NOT private.is_active(auth.uid()) OR NOT private.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Chỉ Super Admin được chuẩn hóa Role.';END IF;
 PERFORM pg_advisory_xact_lock(hashtext('standard_role_catalog'));
 IF EXISTS(SELECT 1 FROM private.standard_role_catalog_runs WHERE after_data IS NOT NULL) THEN RETURN jsonb_build_object('already_applied',true);END IF;
 IF EXISTS(SELECT 1 FROM org_assignments WHERE source='canonical' AND status='active' AND (ends_at IS NULL OR ends_at>now())) THEN RAISE EXCEPTION 'Cần xem trước riêng vì đã có bổ nhiệm ngoài Kinh doanh.';END IF;
 INSERT INTO private.standard_role_catalog_runs(actor_id,before_data,mapping) VALUES(auth.uid(),jsonb_build_object('roles',(SELECT jsonb_agg(to_jsonb(r)) FROM app_roles r),'links',(SELECT jsonb_agg(to_jsonb(l)) FROM base_title_role_links l),'specialties',(SELECT jsonb_agg(to_jsonb(s)) FROM mkt_specialties s)),mapping_) RETURNING id INTO snapshot_;
 FOR spec_ IN SELECT value FROM jsonb_array_elements(mapping_) LOOP
  SELECT * INTO source_ FROM app_roles WHERE id=spec_->>'source';IF NOT FOUND THEN RAISE EXCEPTION 'Thiếu Role nguồn %',spec_->>'source';END IF;
  INSERT INTO app_roles(id,name,description,permissions,catalog_state,catalog_group,catalog_pending) SELECT spec_->>'id',spec_->>'name','Tự cấp tập quyền cá nhân đã kiểm chứng; chức năng quản lý/phạm vi còn chờ.',ARRAY(SELECT p FROM unnest(source_.permissions)p WHERE private.org_role_permission_ready(p)), 'standard',spec_->>'group',ARRAY(SELECT p FROM unnest(source_.permissions)p WHERE NOT private.org_role_permission_ready(p));
  title_:=spec_->>'title';IF title_ IS NOT NULL THEN
   IF NOT EXISTS(SELECT 1 FROM org_titles WHERE id=title_ AND source='base') THEN RAISE EXCEPTION 'Thiếu chức vụ chuẩn %',title_;END IF;
   changes_:=changes_||jsonb_build_array(jsonb_build_object('action','roles','data',jsonb_build_object('id',title_,'roles',jsonb_build_array(jsonb_build_object('role_id',spec_->>'id','is_primary',true,'scope_kind','own','enabled_permissions',(SELECT to_jsonb(permissions) FROM app_roles WHERE id=spec_->>'id'))))));
  END IF;
 END LOOP;
 UPDATE app_roles SET catalog_state='standard',catalog_group=CASE WHEN id IN ('role-super-admin','role-admin','role-viewer') THEN 'Quản trị & Điều hành' WHEN id IN ('role-content-web','role-seo','role-local-seo','role-social','role-video') THEN 'Marketing' WHEN id IN ('role-dong-hang','role-wupj68a6') THEN 'Vận hành' ELSE 'Kinh doanh' END WHERE id IN ('role-super-admin','role-admin','role-viewer','role-content-web','role-seo','role-local-seo','role-social','role-video','role-dong-hang','role-wupj68a6','role-g8qc3q2s','role-xwbmhg3b','role-9h328b84','role-u0fzsvsp','role-kinh-doanh');
 UPDATE app_roles SET catalog_state='compatibility',catalog_group=CASE WHEN id='role-leader-marketing' THEN 'Marketing' WHEN id='role-designer' THEN 'Thiết kế' ELSE 'Vận hành' END WHERE id IN ('role-leader-marketing','role-designer','role-0k2hmw8r','role-xim870m3','role-nhan-su-moi');
 UPDATE app_roles SET catalog_pending=ARRAY(SELECT p FROM unnest(permissions)p WHERE NOT private.org_role_permission_ready(p)) WHERE id IN ('role-content-web','role-seo','role-local-seo','role-social','role-video');
 preview_:=public.org_change('preview',(SELECT revision FROM private.org_control WHERE id),changes_);
 IF jsonb_array_length(coalesce(preview_->'impact','[]'))>0 THEN RAISE EXCEPTION 'Có thay đổi quyền nhân sự; cần xem trước riêng.';END IF;
 PERFORM public.org_change('apply',NULL,NULL,(preview_->>'id')::uuid,'ÁP DỤNG CƠ CẤU','ÁP DỤNG PHÂN QUYỀN:Chuẩn hóa Role theo quyết định quản trị, giữ nguyên nguồn trực tiếp và Kinh doanh');
 UPDATE private.standard_role_catalog_runs SET after_data=jsonb_build_object('roles',(SELECT jsonb_agg(to_jsonb(r)) FROM app_roles r),'links',(SELECT jsonb_agg(to_jsonb(l)) FROM base_title_role_links l),'specialties',(SELECT jsonb_agg(to_jsonb(s)) FROM mkt_specialties s)) WHERE id=snapshot_;
 RETURN jsonb_build_object('snapshot_id',snapshot_,'created',jsonb_array_length(mapping_),'changed_accounts',0,'business_unchanged',true);
END $$;
REVOKE ALL ON FUNCTION public.standard_role_catalog_setup() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.standard_role_catalog_setup() TO authenticated;
COMMENT ON FUNCTION public.standard_role_catalog_setup() IS 'One-time protected catalog registration; preserves all direct/supplemental grants, never appoints staff, and snapshots legacy identities. Existing canonical app_roles remains the permission authority.';